import { expect, type Locator } from "@playwright/test";

export async function expectAutomaticPremiumShine(button: Locator) {
  await expect
    .poll(() =>
      button.evaluate((el) => getComputedStyle(el, "::before").animationName),
    )
    .toBe("premium-button-shine");
  await expect
    .poll(() =>
      button.evaluate((el) =>
        el
          .getAnimations({ subtree: true })
          .some(
            (animation) =>
              animation instanceof CSSAnimation &&
              animation.animationName === "premium-button-shine",
          ),
      ),
    )
    .toBe(true);
  const sweep = await button.evaluate((el) => {
    const animation = el
      .getAnimations({ subtree: true })
      .find(
        (animation) =>
          animation instanceof CSSAnimation &&
          animation.animationName === "premium-button-shine",
      )!;
    const timing = animation.effect!.getTiming();
    animation.pause();
    const positions = [0, 500, 1000, 1500, 2000, 4000, 5999, 6000, 6500].map(
      (time) => {
        animation.currentTime = Number(timing.delay) + time;
        return new DOMMatrix(getComputedStyle(el, "::before").transform).m41;
      },
    );
    animation.play();
    return {
      duration: timing.duration,
      delay: timing.delay,
      iterations:
        timing.iterations === Infinity ? "infinite" : timing.iterations,
      positions,
      events: getComputedStyle(el, "::before").pointerEvents,
      afterContent: getComputedStyle(el, "::after").content,
    };
  });
  expect(sweep.duration).toBe(6000);
  expect(sweep.delay).toBe(3000);
  expect(sweep.iterations).toBe("infinite");
  const [
    start,
    forward,
    end,
    reverse,
    returned,
    resting,
    stillResting,
    repeat,
    repeatedForward,
  ] = sweep.positions;
  expect(start).toBeLessThan(0);
  expect(forward).toBeGreaterThan(start);
  expect(end).toBeGreaterThan(forward);
  expect(reverse).toBeLessThan(end);
  expect(reverse).toBeGreaterThan(returned);
  expect(returned).toBeCloseTo(start, 1);
  expect(resting).toBeCloseTo(start, 1);
  expect(stillResting).toBeCloseTo(start, 1);
  expect(repeat).toBeCloseTo(start, 1);
  expect(repeatedForward).toBeCloseTo(forward, 1);
  expect(sweep.events).toBe("none");
  expect(sweep.afterContent).toBe("none");
}
